    letter-spacing: 1px;
}
.xt-section-3 .xt-section-body {
    color: #7766aa;
    font-weight: 400;
    border-left: 3px solid #c8c0dd !important;
    margin: 0 14px;
    padding: 6px 12px;
    background: #f6f4fa;
}

/* ═══════ 底部 ═══════ */
.xt-footer {
    background: linear-gradient(180deg, #e8edf2 0%, #d0d8e2 100%);
    border-top: 2px solid #8a8a8a;
    color: #888;
    font-size: 10px;
    letter-spacing: 1px;
    padding: 8px 14px;
    text-align: center;
