xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Noto+Serif+SC:wght@400;500&display=swap');

.xt-root {
  --bg: #F5F3F0;
  --card: #FFFFFF;
  --text: #2C2C2C;
  --text-sub: #6E6E6E;
  --accent-red: #C13B3B;
  --accent-stamp: rgba(193, 59, 59, 0.15);
  --border: #DCD9D4;
  --stamp-color: #C13B3B;
  background: var(--bg);
  font-family: 'Inter', 'Noto Serif SC', sans-serif;
  color: var(--text);
  max-height: 75vh;
  overflow-y: auto;
  overflow-x: hidden;
  border-radius: 16px;
  padding: 0 0 20px 0;
  scrollbar-width: thin;
  scrollbar-color: #B0A89F #E8E4DF;
}

.xt-root::-webkit-scrollbar { width: 4px; }
.xt-root::-webkit-scrollbar-track { background: #E8E4DF; }
.xt-root::-webkit-scrollbar-thumb { background: #B0A89F; border-radius: 2px; }

.xt-root::before {
  content: "DEAD LETTER OFFICE · 无法投递邮件归档处";
  display: block;
  padding: 14px 18px 4px;
  font-size: 12px;
  letter-spacing: 2px;
  font-weight: 400;
  color: #8A7E72;
  border-bottom: 1px solid var(--border);
  margin-bottom: 8px;
  text-transform: uppercase;
}

.xt-header {
  padding: 8px 18px 12px !important;
  background: transparent;
  display: flex;
  align-items: center;
  gap: 12px;
}

.xt-avatar {
  width: 44px !important;
  height: 44px !important;
  border-radius: 50% !important;
  border: 1px solid var(--border) !important;
  background: #D9D2C5 !important;
  filter: grayscale(0.4);
}

.xt-name {
  font-size: 16px;
  font-weight: 500;
  color: #3E3A36;
}

.xt-name::after {
  content: "寄件人归档";
  display: block;
  font-size: 11px;
  color: #8A7E72;
  font-weight: 400;
  margin-top: 2px;
  letter-spacing: 0.5px;
}

.xt-text:first-of-type {
  padding: 4px 18px 12px;
  font-size: 13px;
  color: #5E554A;
  font-style: italic;
