/* ========= 折叠展开控制：仅隐藏正文和翻译 ========= */

/* 默认状态：正文和翻译隐藏，其他内容正常显示 */
.xt-action-1 + .xt-section + .xt-text + .xt-text,
.xt-action-1 + .xt-section + .xt-text + .xt-text + .xt-text,
.xt-action-2 + .xt-section + .xt-text + .xt-text,
