  margin-bottom: revert !important;
  padding-top: revert !important;
  padding-bottom: revert !important;
}

#xt-t2:checked ~ .xt-content .xt-action-2 + .xt-section + .xt-text + .xt-text,
#xt-t2:checked ~ .xt-content .xt-action-2 + .xt-section + .xt-text + .xt-text + .xt-text {
  max-height: 400px;
  opacity: 1;
  margin-top: revert !important;
  margin-bottom: revert !important;
  padding-top: revert !important;
  padding-bottom: revert !important;
}

#xt-t3:checked ~ .xt-content .xt-action-3 + .xt-section + .xt-text + .xt-text,
#xt-t3:checked ~ .xt-content .xt-action-3 + .xt-section + .xt-text + .xt-text + .xt-text {
