.xt-section:nth-of-type(5) .xt-list { background: #FFFFFF; border-radius: var(--xt-radius); padding: 8px 16px; margin-bottom: 12px; }
.xt-section:nth-of-type(5) .xt-list-item { padding: 10px 0; border-bottom: 0.5px solid #E5E5EA; font-size: 14px; }
.xt-section:nth-of-type(5) .xt-list-item:last-child { border: none; }

/* =========================================
   完美隔离的 3 页翻页系统 (!important 阻断)
   ========================================= */
@keyframes slideIn { from { opacity: 0; transform: translateX(30px); } to { opacity: 1; transform: translateX(0); } }
.xt-action-1, .xt-action-2 { display: block; background: #FFFFFF; color: var(--xt-accent); padding: 14px; border-radius: 12px; text-align: center; font-weight: 600; font-size: 14px; cursor: pointer; margin-top: 16px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }

/* 【第 1 页】 */
.xt-action-1 ~ * { display: none; } 
.xt-action-1 { display: block; }
.xt-action-1::after { content: "下一页：深度检索 ➔"; }

/* 【第 2 页】 */
#xt-t1:checked ~ .xt-content > * { display: none; } 
