/* 【第 3 页】 */
#xt-t2:checked ~ .xt-content > * { display: none !important; } 
#xt-t2:checked ~ .xt-content .xt-action-2 { display: block !important; background: #E5E5EA; color: #8E8E93; }
#xt-t2:checked ~ .xt-content .xt-action-2::after { content: "← 返回：深度检索"; }
#xt-t2:checked ~ .xt-content .xt-action-2 ~ * { display: block !important; animation: slideIn 0.3s ease; } 

/* 绝密档案印章与美化 */
.xt-section:last-of-type { position: relative; z-index: 1; overflow: hidden; }
.xt-section:last-of-type::after { content: "TOP SECRET"; position: absolute; top: 40px; right: -20px; font-size: 48px; font-weight: 900; font-family: "Courier New", monospace; color: rgba(215, 0, 21, 0.08); border: 6px solid rgba(215, 0, 21, 0.08); padding: 4px 12px; border-radius: 12px; transform: rotate(-25deg); pointer-events: none; z-index: -1; letter-spacing: 2px; }
