xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;700;900&family=Space+Mono&display=swap');

.xt-root {
  --xt-bg: #f9f9f9; 
  --xt-text: #1a252f;
  --xt-text-sub: #7f8c8d;
  --xt-accent: #0f3057; 
  --xt-font: 'Noto Serif SC', serif;

  border: 4px double #d1d8e0;
  padding: 20px 20px 30px 20px;
  box-shadow: 0 15px 35px rgba(15, 48, 87, 0.08);
  position: relative;
  background: var(--xt-bg);
}

/* ================= 1. 顶部剧照 ================= */
.xt-image { margin: 0 0 15px 0 !important; width: 100% !important; height: 180px; border-radius: 2px; position: relative; border: 1px solid #d1d8e0; box-shadow: 0 4px 15px rgba(15, 48, 87, 0.1); }
.xt-image img { width: 100%; height: 100%; object-fit: cover; filter: contrast(110%) saturate(80%); }
.xt-image::before { content: "REC 🔴"; position: absolute; top: 10px; left: 10px; color: #e74c3c; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 2px; animation: blink 1.5s infinite; z-index: 2; }
.xt-image::after { content: "TC: 01:24:36:12"; position: absolute; bottom: 10px; right: 10px; color: rgba(255,255,255,0.9); font-family: 'Space Mono', monospace; font-size: 10px; z-index: 2; }
@keyframes blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

/* ================= 2. 拍摄进度条 ================= */
.xt-bar { margin: 0 0 20px 0; }
.xt-bar-track { background: #e1e4e8; height: 2px; border-radius: 0; }
.xt-bar-fill { background: var(--xt-accent); border-radius: 0; position: relative; overflow: hidden; }
.xt-bar-fill::after { content: ""; position: absolute; top: 0; left: -100%; width: 50%; height: 100%; background: linear-gradient(90deg, transparent, rgba(255,255,255,0.8), transparent); animation: flow 2s infinite; }
@keyframes flow { 100% { left: 200%; } }
.xt-grid-stat-label { font-size: 10px; letter-spacing: 2px; color: var(--xt-text-sub); font-family: 'Space Mono', monospace; }

/* ================= 3. 画外音独白 (8px 极简) ================= */
.xt-quote { background: transparent; border: none; width: 90%; margin: 0 auto 30px auto; padding: 0; line-height: 2.4; font-size: 8px; letter-spacing: 2px; color: var(--xt-accent); font-weight: 700; text-align: center; }
.xt-quote::before, .xt-quote::after { display: none; }

/* ================= 4. 🌟 悬浮吸顶 Tab 切换器 (毛玻璃特效) 🌟 ================= */
.xt-action-1 { 
  display: flex !important; justify-content: space-between; align-items: center; 
  margin: 0 0 30px 0; padding: 0; cursor: pointer; 
  border: 1px solid #d1d8e0; border-radius: 4px; 

  /* 核心吸顶魔法 */
  position: sticky; 
  top: 0; /* 紧贴屏幕顶部 */
  z-index: 999; /* 保证永远在最上层 */
  background: rgba(249, 249, 249, 0.85); /* 半透明底色 */
  backdrop-filter: blur(12px); /* 苹果级毛玻璃模糊特效 */
  box-shadow: 0 4px 20px rgba(15, 48, 87, 0.08); /* 悬浮阴影 */
}
.xt-action-1::before, .xt-action-1::after { content: ""; flex: 1; text-align: center; padding: 12px 0; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 2px; transition: 0.3s; font-weight: bold; }
.xt-action-1::before { content: "CH.1 正片放映"; background: var(--xt-accent); color: #fff; border-radius: 3px 0 0 3px; }
.xt-action-1::after { content: "CH.2 幕后花絮"; background: transparent; color: var(--xt-text-sub); }
#xt-t1:checked ~ .xt-content .xt-action-1::before { background: transparent; color: var(--xt-text-sub); }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "CH.2 幕后花絮"; background: var(--xt-accent); color: #fff; border-radius: 0 3px 3px 0; }

/* ================= 5. 核心词语 ﹂ 戏眼 ﹁ ================= */
.xt-text-dictWord { position: relative; display: table; margin: 20px auto 10px; padding: 10px 25px; font-size: 32px; font-weight: 900; color: var(--xt-accent); letter-spacing: 15px; text-indent: 15px; white-space: nowrap; }
.xt-text-dictWord::before { content: ''; position: absolute; top: 0; right: 0; width: 12px; height: 12px; border-top: 2px solid var(--xt-accent); border-right: 2px solid var(--xt-accent); }
.xt-text-dictWord::after { content: ''; position: absolute; bottom: 0; left: 0; width: 12px; height: 12px; border-bottom: 2px solid var(--xt-accent); border-left: 2px solid var(--xt-accent); }
.xt-text-dictMeaning { text-align: center; color: var(--xt-text-sub); font-size: 12px; font-style: italic; margin-bottom: 35px; }

/* ================= 6. 杂志级脱位排版 (第一页) ================= */
.xt-row { margin-bottom: 30px; align-items: center; }
.xt-row .xt-card { background: transparent; border: none; padding: 0; margin: 0; }
.xt-text-img1, .xt-text-img2 { height: 120px; background-size: cover; background-position: center; border-radius: 2px; color: transparent; box-shadow: 4px 8px 20px rgba(15,48,87,0.15); }

.xt-text-img1 { background-image: url('https://img.heliar.top/file/1776839024552_1776838992594.png'); width: 85%; }
.xt-text-img2 { background-image: url('https://img.heliar.top/file/1776839020765_1776838978765.png'); width: 85%; margin-left: 15%; }

.xt-row:nth-of-type(1) > *:nth-child(2) { margin-top: 50px; padding-left: 15px; }
.xt-text-movieQuote { font-size: 11px; line-height: 1.8; color: var(--xt-text); text-align: right; font-weight: bold; }

/* 🌟 修复后的台词批注：带虚线分割，像手写笔记 🌟 */
.xt-text-movieNote { font-size: 10px; color: var(--xt-text-sub); text-align: right; margin-top: 8px; font-style: italic; border-top: 1px dashed #d1d8e0; padding-top: 6px; display: block; }

.xt-row:nth-of-type(2) > *:nth-child(1) { margin-top: -40px; padding-right: 15px; position: relative; z-index: 2; }
.xt-text-search1, .xt-text-search2 { border: 1px solid #d1d8e0; border-left: 3px solid var(--xt-accent); padding: 8px 12px; margin-bottom: 8px; font-size: 11px; color: var(--xt-text); background: #fff; box-shadow: 2px 2px 8px rgba(0,0,0,0.02); }

/* ================= 7. 第一页：小剧场与杀青附言 ================= */
.xt-section-title { color: var(--xt-accent); font-size: 11px; letter-spacing: 3px; border-bottom: 2px solid var(--xt-accent); padding-bottom: 8px; margin-bottom: 20px; font-family: 'Space Mono', monospace; font-weight: bold; }
.xt-text-auTheaterTitle { background: var(--xt-text); color: #fff; display: inline-block; padding: 4px 12px; font-size: 11px; font-weight: bold; border-radius: 2px; margin-bottom: 10px; letter-spacing: 1px; }
.xt-text-auTheater { border: 1px dashed #d1d8e0; padding: 15px; font-size: 11px; color: var(--xt-text); line-height: 1.8; background: #fff; }

.xt-divider { border-top: 1px dashed #bdc3c7; margin: 30px 0 20px; }
.xt-text-postscript { text-align: center; font-style: italic; color: var(--xt-text-sub); font-size: 13px; margin-bottom: 20px; }

/* ================= 8. 完美隔离两页内容 ================= */
.xt-content > .xt-card { display: none !important; }

#xt-t1:checked ~ .xt-content > .xt-text-dictWord,
#xt-t1:checked ~ .xt-content > .xt-text-dictMeaning,
#xt-t1:checked ~ .xt-content > .xt-row,
#xt-t1:checked ~ .xt-content > .xt-section,
#xt-t1:checked ~ .xt-content > .xt-text-auTheaterTitle,
#xt-t1:checked ~ .xt-content > .xt-text-auTheater,
#xt-t1:checked ~ .xt-content > .xt-divider,
#xt-t1:checked ~ .xt-content > .xt-text-postscript { display: none !important; }

#xt-t1:checked ~ .xt-content > .xt-card { display: block !important; animation: xt-fadeInUp 0.5s ease; }

/* ================= 9. 第二频道：卡片统一样式 ================= */
.xt-content > .xt-card { background: transparent; border: none; padding: 0; margin-bottom: 30px; }
.xt-content > .xt-card > .xt-card-title { color: var(--xt-accent); font-size: 11px; letter-spacing: 3px; border-bottom: 2px solid var(--xt-accent); padding-bottom: 8px; margin-bottom: 20px; font-family: 'Space Mono', monospace; font-weight: bold; text-transform: uppercase; }

/* 群聊气泡 */
.xt-bubbles { background: #f0f2f5; padding: 15px; border-radius: 6px; border: 1px solid #e1e4e8; }
