xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;700;900&family=Space+Mono&display=swap');

.xt-root {
  --xt-bg: #f9f9f9; 
  --xt-text: #1a252f;
  --xt-text-sub: #7f8c8d;
  --xt-accent: #0f3057; 
  --xt-font: 'Noto Serif SC', serif;

  border: 4px double #d1d8e0;
  padding: 20px 20px 30px 20px;
  box-shadow: 0 15px 35px rgba(15, 48, 87, 0.08);
  position: relative;
  background: var(--xt-bg);
}

/* ================= 1. 顶部剧照 ================= */
.xt-image { margin: 0 0 15px 0 !important; width: 100% !important; height: 180px; border-radius: 2px; position: relative; border: 1px solid #d1d8e0; box-shadow: 0 4px 15px rgba(15, 48, 87, 0.1); }
.xt-image img { width: 100%; height: 100%; object-fit: cover; filter: contrast(110%) saturate(80%); }
.xt-image::before { content: "REC 🔴"; position: absolute; top: 10px; left: 10px; color: #e74c3c; font-family: 'Space Mono', monospace; font-size: 11px; letter-spacing: 2px; animation: blink 1.5s infinite; z-index: 2; }
.xt-image::after { content: "TC: 01:24:36:12"; position: absolute; bottom: 10px; right: 10px; color: rgba(255,255,255,0.9); font-family: 'Space Mono', monospace; font-size: 10px; z-index: 2; }
@keyframes blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

/* ================= 2. 拍摄进度条 ================= */
.xt-bar { margin: 0 0 20px 0; }
.xt-bar-track { background: #e1e4e8; height: 2px; border-radius: 0; }
.xt-bar-fill { background: var(--xt-accent); border-radius: 0; position: relative; overflow: hidden; }
.xt-bar-fill::after { content: ""; position: absolute; top: 0; left: -100%; width: 50%; height: 100%; background: linear-gradient(90deg, transparent, rgba(255,255,255,0.8), transparent); animation: flow 2s infinite; }
@keyframes flow { 100% { left: 200%; } }
.xt-grid-stat-label { font-size: 10px; letter-spacing: 2px; color: var(--xt-text-sub); font-family: 'Space Mono', monospace; }

/* ================= 3. 画外音独白 (8px 极简) ================= */
.xt-quote { background: transparent; border: none; width: 90%; margin: 0 auto 30px auto; padding: 0; line-height: 2.4; font-size: 8px; letter-spacing: 2px; color: var(--xt-accent); font-weight: 700; text-align: center; }
.xt-quote::before, .xt-quote::after { display: none; }

/* ================= 4. 🌟 悬浮吸顶 Tab 切换器 (毛玻璃特效) 🌟 ================= */
.xt-action-1 { 
  display: flex !important; justify-content: space-between; align-items: center; 
  margin: 0 0 30px 0; padding: 0; cursor: pointer; 
  border: 1px solid #d1d8e0; border-radius: 4px; 

  /* 核心吸顶魔法 */
  position: sticky; 
  top: 0; /* 紧贴屏幕顶部 */
  z-index: 999; /* 保证永远在最上层 */
  background: rgba(249, 249, 249, 0.85); /* 半透明底色 */
  backdrop-filter: blur(12px); /* 苹果级毛玻璃模糊特效 */
