.xt-root > .xt-content > .xt-card:nth-of-type(1) > .xt-row > .xt-card { background: rgba(255,255,255,0.7) !important; border: 1px solid var(--pink-border) !important; border-radius: 8px !important; padding: 10px !important; box-shadow: 2px 4px 10px rgba(0,0,0,0.02) !important; }
